 function openGuide(guide){location.hash=window.MytheraWiki.link(guide);}
 function renderGuides(root,beginner=false){const guideRows=beginner?profile.guides.filter(g=>['readme','informations/publish-your-docs','informations/general-options','gameplay/wands-and-rods','systems/bed-system','systems/loot-and-exp-analyzer'].includes(g.path)):profile.guides;if(ctx.isMythera&&location.hash.startsWith('#mundo/guia/')){window.MytheraWiki.render(root,(()=>{try{return decodeURIComponent(location.hash.slice(12));}catch{return '';}})());return;}if(ctx.isMythera&&location.hash==='#mundo/locais'){renderMap(root);return;}if(ctx.isMythera&&!beginner){window.MytheraSystems.render(root);return;}if(!ctx.isMythera){root.innerHTML=`<section class="world-workspace"><div class="world-page-heading"><p class="eyebrow">TIBIA 7.4 · CLÁSSICO</p><h1>Biblioteca clássica</h1><p>Os sistemas desta página pertencem ao Mythera. No modo clássico, consulte a biblioteca de referência.</p></div><a class="world-button" href="#explorador/search">Pesquisar na biblioteca clássica →</a><a class="world-button" href="#inicio">Voltar ao início clássico</a></section>`;return;}let page=0;root.innerHTML=`<section class="world-workspace">${heading(beginner?'Primeiros passos no Mythera':'Sistemas do Mythera',beginner?'Comece pelas regras, opções do cliente e recursos para sua primeira jornada.':'Encontre um assunto e abra o guia para consultar detalhes e fonte.')}<div class="world-filters"><label>Buscar assunto<input type="search" data-world-guide-query placeholder="Tumbas, rituais, mineração…"></label><label>Categoria<select data-world-guide-category><option value="">Todas as categorias</option>${[...new Set(guideRows.map(g=>g.category))].sort().map(c=>`<option>${esc(c)}</option>`).join('')}</select></label><label>Estado<select data-world-guide-status><option value="">Todos</option>${Object.entries(states).map(([k,v])=>`<option value="${k}">${v}</option>`).join('')}</select></label></div><p class="world-result-count" data-world-guide-count role="status"></p><div data-world-guides class="library-grid"></div><div class="world-pager"><button type="button" class="world-button secondary" data-guide-prev>Anterior</button><span data-guide-page></span><button type="button" class="world-button secondary" data-guide-next>Próxima</button></div></section>`;
  const paint=()=>{const q=norm(root.querySelector('[data-world-guide-query]').value),category=root.querySelector('[data-world-guide-category]').value,state=root.querySelector('[data-world-guide-status]').value,rows=guideRows.filter(g=>(!category||g.category===category)&&(!state||g.status===state)&&norm(g.title+' '+g.summary+' '+g.category).includes(q));page=Math.min(page,Math.max(0,Math.ceil(rows.length/9)-1));root.querySelector('[data-world-guide-count]').textContent=rows.length+' assuntos encontrados';root.querySelector('[data-guide-page]').textContent=(page+1)+' / '+Math.max(1,Math.ceil(rows.length/9));const out=root.querySelector('[data-world-guides]');out.innerHTML=rows.slice(page*9,page*9+9).map(g=>libraryCard({attribute:'data-guide-open',key:g.id,name:g.title,category:g.category,art:atlasIcon,badge:states[g.status]||'Mythera',facts:[],note:g.summary,footer:'Ler guia e consultar fonte'})).join('')||'<p class="world-empty">Nenhum assunto encontrado.</p>';out.querySelectorAll('[data-guide-open]').forEach(b=>b.onclick=()=>openGuide(profile.guides.find(g=>g.id===b.dataset.guideOpen)));root.querySelector('[data-guide-prev]').disabled=page===0;root.querySelector('[data-guide-next]').disabled=(page+1)*9>=rows.length;};const reset=()=>{page=0;paint();};root.querySelector('[data-world-guide-query]').oninput=reset;root.querySelector('[data-world-guide-category]').onchange=reset;root.querySelector('[data-world-guide-status]').onchange=reset;root.querySelector('[data-guide-prev]').onclick=()=>{page--;paint();};root.querySelector('[data-guide-next]').onclick=()=>{page++;paint();};const topics={rituais:'rituais',tumbas:'tumbas',crafting:'crafting',magias:'magias'};root.querySelector('[data-world-guide-query]').value=topics[location.hash.split('/')[1]]||'';paint();
 }
 function renderHome(root){if(typeof window.renderHome==='function'){window.renderHome(root);const title=root.querySelector('#home-account-title');if(title)title.textContent='Organize sua jornada no Mythera.';const description=root.querySelector('[data-home-account-description]');if(description)description.textContent='Organize seu personagem, seus planos e sua evolução com sua conta da comunidade.';const reference=root.querySelector('.home-reference-note');if(reference)reference.textContent='Mythera selecionado · base Tibia 7.4 com acréscimos e alterações do servidor.';window.MytheraTrade?.mountHome(root);return;}root.innerHTML=`<section class="world-workspace"><section class="world-home-hero"><div><p class="eyebrow">MYTHERA · SEU SERVIDOR SELECIONADO</p><h1>Seu guia para<br>jogar no Mythera.</h1><p>Encontre criaturas, equipamentos, magias e serviços. Prepare sua próxima aventura com a biblioteca 7.4 e as novidades do servidor.</p><div class="world-actions"><a class="world-button" href="#catalog/itens">Explorar ${items.length} itens</a><a class="world-button secondary" href="#mundo">Conhecer os sistemas</a></div></div><img src="assets/vocation-knight.webp" width="500" height="500" alt="Cavaleiro do Tibia Command" fetchpriority="high"></section><section class="world-home-collections" aria-label="Conteúdo do Mythera">${[['criaturas','01','Criaturas',`${creatureLibrary.length} fichas com XP, loot e eventos identificados.`],['catalog/itens','02','Itens e equipamentos',`${items.length} fichas · base 7.4 e catálogo Mythera.`],['catalog/magias','03','Magias','Requisitos, palavras mágicas e professores.'],['catalog/npcs','04','NPCs e serviços','Comerciantes, professores e preços por origem.'],['explorador/cities','05','Cidades e regiões','Serviços por local, chaves e referências.'],['mundo','06','Sistemas do servidor','Rituais, elites, tumbas e crafting.']].map(([href,n,title,description])=>`<a class="world-collection" href="#${href}"><span class="world-step">${n}</span><h2>${title}</h2><p>${description}</p><span class="world-card-link">Explorar →</span></a>`).join('')}</section><div class="world-section-heading"><h2>Planeje sua próxima sessão</h2></div><section class="world-home-tools">${[['calculadora','Level e XP','Previsão com a progressão própria após o level 160.'],['mana','Mana e runas','Regeneração da vocação e produção com parâmetros editáveis.'],['conta/personagem','Meu personagem','Ficha, anotações e planos numa conta de demonstração.']].map(([href,title,description])=>`<a href="#${href}" class="world-tool"><h3>${title}</h3><p>${description}</p><span class="world-card-link">Abrir →</span></a>`).join('')}</section>${note('Você está na versão de testes. Conteúdo Mythera e referência clássica são separados pelo seletor do cabeçalho. Fontes consultadas em 18/10/2026.')}</section>`;}
