 function referenceArt(r){const image=r.image||(r.recordType==='npc'?npcImage(r):null)||(r.mob?creatureImage({name:r.mob}):null);if(image)return `<img class="catalog-sprite" src="${esc(image)}" alt="" loading="lazy" decoding="async">`;const kind=r.recordType==='npc'?'npc':/ritual/i.test(r.activityKind||'')?'ritual':r.recordType==='hunt'?'hunt':r.recordType==='quest'?'quest':'guide';return libraryGraphic(kind,'Ilustração da categoria · '+(r.recordType==='npc'?'NPC sem retrato confirmado':r.activityKind||r.recordType||'guia'));}
 function recordLinks(links){return links?.length?`<section><h3>Conteúdo relacionado</h3><div class="world-actions">${links.map(l=>`<a class="action secondary" href="${esc(l.href)}">${esc(l.label)} →</a>`).join('')}</div></section>`:'';}
 function recordSheet(r){if(r.recordType==='quest'){const mapped=window.mappedQuestMarkup?.(r);if(mapped)return mapped;}const list=(title,values)=>values?.length?`<section><h3>${title}</h3><ul>${values.map(v=>`<li>${esc(v)}</li>`).join('')}</ul></section>`:'';return `<article class="world-record-sheet"><div class="world-record-heading"><span class="library-art">${referenceArt(r)}</span><div><p class="eyebrow">${esc(r.origin==='classic'?'BASE 7.4':'MYTHERA')} · ${esc(r.recordType==='hunt'?'HUNT':r.recordType==='quest'?'QUEST':'GUIA')}</p><h2>${esc(r.name)}</h2></div></div><p>${esc(r.description||r.access||'')}</p>${r.facts?libraryFacts(r.facts):''}${list('Requisitos de acesso',r.needs)}${list('Preparação',r.preparation)}${list('Percurso de referência',r.rotation||r.steps)}${list('Recompensas',r.rewards)}${list('Locais documentados',r.locations)}${list('Ainda sem confirmação',r.limits)}${r.evidence?note(esc(r.evidence)):''}${recordLinks(r.links)}${r.rewardNote?note(esc(r.rewardNote)):''}${r.danger?`<section><h3>Atenção no local</h3><p>${esc(r.danger)}</p></section>`:''}${r.origin==='classic'?note('Guia herdado da base Tibia 7.4. O Mythera pode alterar percursos, acessos e recompensas; confira as condições no cliente antes de iniciar.'):''}${r.tip?note(esc(r.tip)):''}${r.questId?`<div class="world-actions"><a class="world-button secondary" href="#quest/${encodeURIComponent(r.questId)}">Consultar guia da quest</a></div>`:''}${r.source?source(r.source,r.status==='reference'?'Consultar referência clássica':'Consultar fonte do servidor'):''}${r.extraSource?source(r.extraSource,'Alteração Mythera'):''}${(r.sources||[]).filter(u=>u!==r.source).map(u=>source(u,'Fonte complementar')).join(' ')}${r.origin==='classic'&&r.recordType==='hunt'?`<div class="world-actions"><a href="#hunt-map/${encodeURIComponent(r.id)}" class="world-button secondary">Ver referência no mapa 7.4</a></div>`:''}</article>`;}
 function openRecord(r){if(r.recordType==='npc'){location.hash='#npc/'+encodeURIComponent(r.name);return;}if(r.recordType==='item'){openItem(r);return;}openCatalogDialog(recordSheet(r));window.LibrarySearch?.connect(r.recordType,r);if(r.recordType==='quest')window.bindQuestGuideDetails?.(document.querySelector('#detail-body'),r.id);document.querySelectorAll('#detail a[href^="#"]').forEach(a=>a.addEventListener('click',()=>document.querySelector('#detail').close()));}
 function directory(root,title,description,rows){root.dataset.locationDirectory=String(rows.some(r=>r.locationCard));root.innerHTML=`<section class="world-workspace world-directory">${heading(title,description)}<div class="world-filters"><label>Pesquisar<input type="search" data-domain-query placeholder="Nome, cidade ou informação…"></label><label>Origem<select data-domain-origin><option value="">Todas as origens</option><option value="classic">Base 7.4</option><option value="mythera">Mythera</option></select></label></div><p class="world-result-count" data-domain-count role="status" aria-live="polite"></p><div class="library-grid" data-domain-results></div><button type="button" class="world-button secondary mythera-creature-more" data-domain-more>Mostrar mais</button></section>`;let limit=24;const paint=()=>{const q=norm(root.querySelector('[data-domain-query]').value).trim().split(/\s+/).filter(Boolean),origin=root.querySelector('[data-domain-origin]').value,filtered=rows.filter(r=>(!origin||(r.origin||'mythera')===origin)&&q.every(t=>norm([r.name,r.description,r.city,r.mob,r.aliases].join(' ')).includes(t)));root.querySelector('[data-domain-count]').textContent=filtered.length+' registros · '+Math.min(limit,filtered.length)+' exibidos';const out=root.querySelector('[data-domain-results]');out.innerHTML=filtered.slice(0,limit).map((r,i)=>libraryCard({attribute:'data-directory-open',key:i,name:r.name,category:r.recordType==='hunt'?(r.activityKind||'Hunt'):r.recordType==='quest'?'Quest':r.recordType==='npc'?'NPC · '+r.city:r.city||'Guia',art:referenceArt(r),badge:r.origin==='classic'?'Base 7.4':'Mythera',facts:r.facts||[],note:(r.description||r.access||'').slice(0,120),footer:r.city||'Detalhes e fonte'})).join('')||'<p class="world-empty">Nenhum resultado para esta busca.</p>';out.querySelectorAll('[data-directory-open]').forEach(b=>b.onclick=()=>openRecord(filtered[Number(b.dataset.directoryOpen)]));root.querySelector('[data-domain-more]').hidden=filtered.length<=limit;};root.querySelector('[data-domain-query]').oninput=()=>{limit=24;paint();};root.querySelector('[data-domain-origin]').onchange=()=>{limit=24;paint();};root.querySelector('[data-domain-more]').onclick=()=>{limit+=24;paint();};paint();}
 const ritualRows=()=>domain.hunts.map(h=>({...h,id:'mythera-'+tradeKey(h.name),origin:'mythera',recordType:'hunt',status:'official',facts:[['Level mínimo',h.level],['Grupo máximo',h.party]],source:guideSource(/ritual/i)}));
 function huntRows(){return [...(window.CLASSIC_HUNTS||[]).map(h=>({...h,origin:'classic',recordType:'hunt',status:'reference',description:h.access,source:h.sources?.[0],facts:[['Cidade',h.city],['Level sugerido',h.level],['Criatura',h.mob],['Objetivo',h.goal]],...(h.city==='Ankrahmun'&&/tomb/i.test(h.id+' '+h.name)?{description:h.access+' O Mythera documenta a rotação de sete tumbas de Ankrahmun, mas não enumera as participantes nessa página. Confirme esta entrada com Tothdral antes de viajar.',extraSource:guideSource(/tomb/i)}:{})})),...ritualRows(),{id:'mythera-tombs',name:'Tumbas de Ankrahmun · rotação',origin:'mythera',recordType:'hunt',city:'Ankrahmun',description:'Sete tumbas alternam diariamente; apenas uma abre por dia. Pergunte “tomb” a Tothdral. Ao sair de uma tumba fechada por logout, o próximo login leva à entrada. A ordem de rotação não foi publicada.',source:guideSource(/tomb/i)},{id:'mythera-daily-bosses',name:'Daily bosses',origin:'mythera',recordType:'hunt',description:'Intervalo de 20h. Consulte requisitos e localizações no Bestiary Bosses do cliente.',source:guideSource(/daily.*boss/i)},...window.MytheraAdventureReview.extraHunts].map(window.MytheraAdventureReview.decorate);}
 function questLibrary(){const rows=(typeof QUESTS!=='undefined'?QUESTS:window.CLASSIC_QUEST_CATALOG||[]).map(q=>({...q,origin:'classic',recordType:'quest',status:'reference',description:q.location,source:q.sources?.[0],facts:[['Cidade',q.city],['Level da porta',q.level||'Sem porta de level'],['Grupo',q.group||'Consultar guia']]}));for(const q of domain.quests){const index=rows.findIndex(r=>tradeKey(r.name)===tradeKey(q.name)),old=rows[index];const record={...q,id:old?.id||'mythera-'+tradeKey(q.name),origin:'mythera',recordType:'quest',source:guideSource(q.name==='Iron Hammer'?/craft/i:/ritual/i)};if(index>=0)rows[index]=record;else rows.push(record);}return rows.map(window.MytheraAdventureReview.decorate);}
 const creatureImages={"Bonebeast":{"image":"assets/mythera-bonebeast.gif","source":"https://www.tibiawiki.com.br/wiki/Bonebeast"},"Bat":{"image":"assets/mythera-bat.gif","source":"https://www.tibiawiki.com.br/wiki/Bat"},"Frost Dragon":{"image":"assets/mythera-frost-dragon.gif","source":"https://www.tibiawiki.com.br/wiki/Frost_Dragon"},"Undead Dragon":{"image":"assets/mythera-undead-dragon.gif","source":"https://www.tibiawiki.com.br/wiki/Undead_Dragon"},"Crystal Spider":{"image":"assets/mythera-crystal-spider.gif","source":"https://www.tibiawiki.com.br/wiki/Crystal_Spider"},"Skeleton Warrior":{"image":"assets/mythera-skeleton-warrior.gif","source":"https://www.tibiawiki.com.br/wiki/Skeleton_Warrior"}};
 function creatureImage(c){return creatureImages[c.name]?.image||window.DATA?.monsters?.[c.name.toLowerCase()]||null;}
 function creatureVisual(c){const image=creatureImage(c);return image?`<img class="catalog-sprite" src="${esc(image)}" alt="" loading="lazy" decoding="async">`:libraryGraphic('creature','Criatura · sprite ainda não confirmado');}
 // XP and dropped item names follow the classic base by the owner's confirmation on 18/10/2026.
